import * as zlib from 'node:zlib';

function report(label: string, fn: () => void): void {
  try {
    fn();
    console.log(label, 'returned');
  } catch (e: any) {
    console.log(label, e.name, e.code, e.message);
  }
}

function roundTrip(label: string, value: Buffer | DataView | ArrayBuffer | Uint8Array): Promise<void> {
  return new Promise<void>((resolve: () => void) => {
    zlib.gzip(value, (err: any, packed: Buffer) => {
      if (err) {
        console.log(label, 'error', err.message);
        resolve();
        return;
      }
      zlib.gunzip(packed, (err2: any, back: Buffer) => {
        console.log(label, err2 ? err2.message : back.toString());
        resolve();
      });
    });
  });
}

async function main(): Promise<void> {
  report('no callback', () => zlib.gzip(Buffer.from('x')));
  report('callback is a number', () => zlib.gzip(Buffer.from('x'), 5 as any));
  report('bad chunk with callback', () => zlib.gzip(5 as any, (e: any, r: Buffer) => {}));
  report('level out of range with callback', () => zlib.deflate(Buffer.from('x'), { level: 99 }, (e: any, r: Buffer) => {}));
  report('options before callback', () => zlib.deflate(5 as any, { level: 99 }));
  report('brotli ignores level', () => zlib.brotliCompress(Buffer.from('hello'), { level: 99 } as any, (e: any, r: Buffer) => {}));
  await roundTrip('dataview', new DataView(new Uint8Array([104, 105, 33]).buffer));
  await roundTrip('arraybuffer', new Uint8Array([104, 105, 33]).buffer);
  await roundTrip('uint8array subview', new Uint8Array([0, 104, 105, 33]).subarray(1));
  await roundTrip('empty null', null as any);
  console.log('done');
}
